import json
import logging
import os
import time
from datetime import datetime
from pathlib import Path
from typing import List, Dict, Any, Optional

from utils import api_request_with_backoff, validate_json_schema

# Configure logging
logging.basicConfig(
    level=logging.INFO,
    format='%(asctime)s - %(levelname)s - %(message)s'
)
logger = logging.getLogger(__name__)

def load_repos(repos_path: str) -> List[Dict[str, Any]]:
    """Load the list of repositories from the JSON file generated by T012a."""
    if not os.path.exists(repos_path):
        raise FileNotFoundError(f"Repository list file not found: {repos_path}")
    
    with open(repos_path, 'r', encoding='utf-8') as f:
        data = json.load(f)
    
    if not isinstance(data, list):
        raise ValueError(f"Expected list of repos in {repos_path}, got {type(data)}")
    
    return data

def fetch_prs_for_repo(repo_name: str, since: Optional[str] = None) -> List[Dict[str, Any]]:
    """
    Fetch all PRs for a given repository.
    Uses the GitHub Search API to find PRs.
    """
    # GitHub Search API for PRs: q=is:pr repo:owner/name
    # We need to paginate to get all PRs
    base_url = "https://api.github.com/search/issues"
    prs = []
    page = 1
    per_page = 100  # Max allowed
    
    while True:
        params = {
            "q": f"is:pr repo:{repo_name} is:merged",
            "sort": "created",
            "order": "asc",
            "per_page": per_page,
            "page": page
        }
        
        logger.info(f"Fetching PRs for {repo_name}, page {page}")
        response, headers = api_request_with_backoff(base_url, params)
        
        if not response:
            logger.warning(f"Failed to fetch PRs for {repo_name} after retries")
            break
        
        items = response.get("items", [])
        if not items:
            break
        
        # Filter to ensure we only get PRs (search API returns issues too)
        prs.extend([item for item in items if item.get("pull_request")])
        
        # Check rate limits
        remaining = int(headers.get("X-RateLimit-Remaining", 0))
        if remaining < 10:
            logger.warning(f"Rate limit low ({remaining}), waiting...")
            reset_time = int(headers.get("X-RateLimit-Reset", 0))
            if reset_time:
                wait_time = max(reset_time - int(time.time()) + 10, 60)
                time.sleep(wait_time)
        
        if len(items) < per_page:
            break
        
        page += 1
        
        # Safety break to prevent infinite loops
        if page > 50:
            logger.warning(f"Reached max page limit for {repo_name}")
            break
    
    logger.info(f"Fetched {len(prs)} PRs for {repo_name}")
    return prs

def fetch_commits_for_pr(pr_url: str) -> List[Dict[str, Any]]:
    """
    Fetch all commits for a specific PR.
    """
    # The commits endpoint for a PR
    # pr_url is typically like: https://api.github.com/repos/owner/repo/pulls/123
    # We need to append /commits
    commits_url = f"{pr_url}/commits"
    
    commits = []
    page = 1
    per_page = 100
    
    while True:
        params = {"per_page": per_page, "page": page}
        
        logger.debug(f"Fetching commits for PR at {pr_url}, page {page}")
        response, headers = api_request_with_backoff(commits_url, params)
        
        if not response:
            logger.warning(f"Failed to fetch commits for PR at {pr_url}")
            break
        
        if not isinstance(response, list):
            logger.error(f"Unexpected response type for commits: {type(response)}")
            break
        
        if not response:
            break
        
        commits.extend(response)
        
        if len(response) < per_page:
            break
        
        page += 1
        
        # Safety break
        if page > 50:
            break
    
    return commits

def parse_iso_datetime(iso_string: str) -> Optional[datetime]:
    """Parse ISO 8601 datetime string."""
    if not iso_string:
        return None
    try:
        # Handle 'Z' suffix
        if iso_string.endswith('Z'):
            iso_string = iso_string[:-1] + '+00:00'
        return datetime.fromisoformat(iso_string)
    except ValueError:
        logger.warning(f"Could not parse datetime: {iso_string}")
        return None

def calculate_turnaround_hours(created_at: str, merged_at: str) -> Optional[float]:
    """Calculate turnaround time in hours."""
    created = parse_iso_datetime(created_at)
    merged = parse_iso_datetime(merged_at)
    
    if not created or not merged:
        return None
    
    delta = merged - created
    return delta.total_seconds() / 3600

def process_pr_data(repo_name: str, pr: Dict[str, Any]) -> Optional[Dict[str, Any]]:
    """
    Process a single PR to extract relevant data including commits.
    """
    pr_id = str(pr.get("number"))
    pr_url = pr.get("url")
    
    if not pr_url:
        logger.warning(f"PR {pr_id} missing URL in {repo_name}")
        return None
    
    created_at = pr.get("created_at")
    merged_at = pr.get("merged_at")
    
    if not merged_at:
        logger.debug(f"PR {pr_id} in {repo_name} not merged, skipping")
        return None
    
    turnaround_hours = calculate_turnaround_hours(created_at, merged_at)
    
    # Fetch commits for this PR
    commits = fetch_commits_for_pr(pr_url)
    
    if not commits:
        logger.warning(f"No commits found for PR {pr_id} in {repo_name}")
        # Still return the PR data even if no commits, but mark it
        commit_messages = []
    else:
        commit_messages = [
            commit.get("commit", {}).get("message", "")
            for commit in commits
        ]
    
    return {
        "repo_name": repo_name,
        "pr_id": pr_id,
        "created_at": created_at,
        "merged_at": merged_at,
        "turnaround_hours": turnaround_hours,
        "commit_messages": commit_messages,
        "commit_count": len(commits),
        "labels": [label.get("name") for label in pr.get("labels", [])],
        "author": pr.get("user", {}).get("login")
    }

def main():
    """Main execution function for T012b."""
    project_root = Path(__file__).parent.parent
    repos_path = project_root / "data" / "raw" / "repos.json"
    output_path = project_root / "data" / "raw" / "pr_commits.json"
    
    if not repos_path.exists():
        logger.error(f"Repos file not found at {repos_path}. Run T012a first.")
        return
    
    logger.info(f"Loading repos from {repos_path}")
    repos = load_repos(str(repos_path))
    logger.info(f"Loaded {len(repos)} repositories")
    
    all_pr_data = []
    skipped_repos = 0
    processed_repos = 0
    
    for repo_info in repos:
        repo_name = repo_info.get("name")
        if not repo_name:
            logger.warning("Skipping repo entry without name")
            continue
        
        logger.info(f"Processing repository: {repo_name}")
        
        try:
            prs = fetch_prs_for_repo(repo_name)
            
            if len(prs) < 50:
                logger.warning(f"Repo {repo_name} has only {len(prs)} PRs (threshold: 50). Skipping.")
                skipped_repos += 1
                continue
            
            processed_repos += 1
            
            for pr in prs:
                pr_data = process_pr_data(repo_name, pr)
                if pr_data:
                    all_pr_data.append(pr_data)
                    
                # Rate limiting safety
                time.sleep(1)
                
        except Exception as e:
            logger.error(f"Error processing {repo_name}: {e}", exc_info=True)
            continue
    
    logger.info(f"Processing complete. Repos: {processed_repos} processed, {skipped_repos} skipped.")
    logger.info(f"Total PRs with commits extracted: {len(all_pr_data)}")
    
    # Save output
    output_path.parent.mkdir(parents=True, exist_ok=True)
    with open(output_path, 'w', encoding='utf-8') as f:
        json.dump(all_pr_data, f, indent=2, default=str)
    
    logger.info(f"Saved results to {output_path}")
    
    # Validate schema
    schema_path = project_root / "contracts" / "pull_request.schema.yaml"
    if schema_path.exists():
        # Simple validation check (full validation logic is in utils)
        if validate_json_schema(all_pr_data[0] if all_pr_data else {}, str(schema_path)):
            logger.info("Schema validation passed")
        else:
            logger.warning("Schema validation failed")

if __name__ == "__main__":
    main()